use i2r_candidate::{mirror, Tree};

struct NoTraits(i32);

fn assert_leaf<A>(t: &Tree<A>) {
    match t {
        Tree::Leaf => {}
        Tree::Node(_, _, _) => panic!("expected Leaf"),
    }
}

#[test]
fn mirror_leaf_returns_leaf() {
    let out: Tree<NoTraits> = mirror(Tree::<NoTraits>::Leaf);
    assert_leaf(&out);
}

#[test]
fn mirror_one_node_stays_single_node_with_value() {
    let input: Tree<NoTraits> =
        Tree::Node(Box::new(Tree::Leaf), NoTraits(7), Box::new(Tree::Leaf));
    let out = mirror(input);
    match out {
        Tree::Node(l, x, r) => {
            assert_eq!(x.0, 7);
            assert_leaf(&*l);
            assert_leaf(&*r);
        }
        Tree::Leaf => panic!("expected Node"),
    }
}

#[test]
fn mirror_deeper_swaps_recursively_mirrored_children() {
    let left: Tree<NoTraits> =
        Tree::Node(Box::new(Tree::Leaf), NoTraits(1), Box::new(Tree::Leaf));
    let right: Tree<NoTraits> = Tree::Node(
        Box::new(Tree::Node(
            Box::new(Tree::Leaf),
            NoTraits(3),
            Box::new(Tree::Leaf),
        )),
        NoTraits(4),
        Box::new(Tree::Leaf),
    );
    let input: Tree<NoTraits> = Tree::Node(Box::new(left), NoTraits(2), Box::new(right));

    let out = mirror(input);
    match out {
        Tree::Node(out_l, out_x, out_r) => {
            assert_eq!(out_x.0, 2);

            match &*out_l {
                Tree::Node(l2, x2, r2) => {
                    assert_eq!(x2.0, 4);
                    assert_leaf(&**l2);
                    match &**r2 {
                        Tree::Node(l3, x3, r3) => {
                            assert_eq!(x3.0, 3);
                            assert_leaf(&**l3);
                            assert_leaf(&**r3);
                        }
                        Tree::Leaf => panic!("expected Node at right-right"),
                    }
                }
                Tree::Leaf => panic!("expected Node at left"),
            }

            match &*out_r {
                Tree::Node(l4, x4, r4) => {
                    assert_eq!(x4.0, 1);
                    assert_leaf(&**l4);
                    assert_leaf(&**r4);
                }
                Tree::Leaf => panic!("expected Node at right"),
            }
        }
        Tree::Leaf => panic!("expected Node at root"),
    }
}

